 private int dp(int v){return Math.round(v*getResources().getDisplayMetrics().density);}
 protected void onMeasure(int widthSpec,int heightSpec){boolean next=getResources().getConfiguration().orientation==android.content.res.Configuration.ORIENTATION_LANDSCAPE||(View.MeasureSpec.getMode(heightSpec)!=View.MeasureSpec.UNSPECIFIED&&View.MeasureSpec.getSize(heightSpec)<dp(320));if(status!=null&&next!=compact){compact=next;heading.setVisibility(compact?GONE:VISIBLE);status.setVisibility(compact?GONE:VISIBLE);status.setMaxLines(compact?1:4);status.setTextSize(compact?11:14);LinearLayout tools=(LinearLayout)toolViewport.getChildAt(0);for(int i=0;i<tools.getChildCount();i++)if(tools.getChildAt(i) instanceof Button){Button b=(Button)tools.getChildAt(i);b.setTextSize(compact?12:14);b.setSingleLine(compact);}}super.onMeasure(widthSpec,heightSpec);}
 private LinearLayout column(){LinearLayout v=new LinearLayout(getContext());v.setOrientation(VERTICAL);return v;}
 private LinearLayout row(){LinearLayout v=new LinearLayout(getContext());v.setOrientation(HORIZONTAL);return v;}
