 private void label(LinearLayout parent,String t){TextView v=new TextView(getContext());v.setText(t);parent.addView(v);}
 private Button button(LinearLayout parent,String t,Action fn){Button b=new Button(getContext());b.setText(t);b.setMinHeight(dp(48));parent.addView(b,new LayoutParams(-2,dp(48)));b.setOnClickListener(v->{if(modelUiOwner()&&hasWindowFocus()&&b.isShown()&&b.isEnabled())guard(fn);});return b;}
 private void adapter(Spinner spinner,List<String>values){ArrayAdapter<String>a=new ArrayAdapter<String>(getContext(),android.R.layout.simple_spinner_item,values){public View getView(int p,View reuse,android.view.ViewGroup parent){TextView t=(TextView)super.getView(p,reuse,parent);t.setTextColor(dark?Color.WHITE:Color.rgb(23,34,53));return t;}public View getDropDownView(int p,View reuse,android.view.ViewGroup parent){TextView t=(TextView)super.getDropDownView(p,reuse,parent);t.setTextColor(dark?Color.WHITE:Color.rgb(23,34,53));t.setBackgroundColor(dark?Color.rgb(32,46,66):Color.WHITE);t.setMinHeight(dp(48));return t;}};a.setDropDownViewResource(android.R.layout.simple_spinner_dropdown_item);spinner.setAdapter(a);}
 private android.text.TextWatcher watcher(){return new android.text.TextWatcher(){public void beforeTextChanged(CharSequence s,int a,int count,int after){}public void onTextChanged(CharSequence s,int a,int before,int count){if(!filling){removeCallbacks(saveDraft);postDelayed(saveDraft,300);}}public void afterTextChanged(android.text.Editable e){}};}
 private boolean modelUiOwner(){return isAttachedToWindow()&&isShown()&&getWindowVisibility()==VISIBLE;}
 private void invalidateModelUi(){modelUiGeneration++;if(modelHistoryDialog!=null){android.app.AlertDialog old=modelHistoryDialog;modelHistoryDialog=null;old.dismiss();}if(!modelPending.isEmpty()){modelPending="";readerText="";readerOffset=0;show(0);}}
 private void showModelHistory()throws Exception{List<String>ids=modelArchive.list();QuantResearchModel.need(!ids.isEmpty(),"尚无已核对模型结果。使用导入选择完整结果包；本机未运行Python模型训练。");final long generation=modelUiGeneration;final android.view.ViewParent parent=getParent();android.app.AlertDialog dialog=new android.app.AlertDialog.Builder(getContext()).setTitle("完整模型结果 · 手机只读复核").setNegativeButton("关闭",null).setItems(ids.toArray(new String[0]),(selected,index)->{android.app.AlertDialog current=(android.app.AlertDialog)selected;if(modelHistoryDialog==current&&modelUiGeneration==generation&&getParent()==parent&&modelUiOwner()&&current.isShowing()&&current.getWindow()!=null&&current.getWindow().getDecorView().hasWindowFocus())guard(()->openModelResult(ids.get(index)));}).create();modelHistoryDialog=dialog;dialog.setOnDismissListener(closed->{if(modelHistoryDialog==dialog){modelHistoryDialog=null;modelUiGeneration++;}});dialog.show();}
 private void guard(Action a){try{a.run();}catch(Exception e){if(status!=null)status.setText(e.getMessage()==null?e.toString():e.getMessage());}}
 private void show(int m){mode=m;form.setVisibility(m==0?VISIBLE:GONE);results.setVisibility(m==1?VISIBLE:GONE);readPage.setVisibility(m==2?VISIBLE:GONE);}
 private String datasetId(){int i=datasetPicker.getSelectedItemPosition();return i>=0&&i<datasetIds.size()?datasetIds.get(i):"";}
 private void fill(JSONObject c)throws Exception{filling=true;familyPicker.setSelection(Math.max(0,Arrays.asList(QuantResearchModel.FAMILIES).indexOf(c.getString("family"))));for(String k:KEYS)fields.get(k).setText(c.get(k).toString());parameters.setText(c.getJSONArray("parameters").toString(2));filling=false;}
 private JSONObject config()throws Exception{JSONObject c=new JSONObject().put("family",QuantResearchModel.FAMILIES[familyPicker.getSelectedItemPosition()]);for(String k:KEYS){String raw=fields.get(k).getText().toString().trim();QuantResearchModel.need(raw.matches("[+]?(?:[0-9]+(?:\\.[0-9]*)?|\\.[0-9]+)(?:[eE][+-]?[0-9]+)?"),"无效参数: "+k);double n=Double.parseDouble(raw);QuantResearchModel.need(Double.isFinite(n),"无效参数: "+k);c.put(k,n);}c.put("parameters",QuantResearchJson.array(parameters.getText().toString()));QuantResearchModel.validateConfig(c);return c;}
 private void refresh()throws Exception{String previous=datasetId();datasetIds.clear();List<String>names=new ArrayList<>();history.removeAllViews();JSONArray rows=store.read().getJSONArray("records");for(int i=0;i<rows.length();i++){JSONObject r=rows.getJSONObject(i);String id=r.getString("id"),kind=r.getString("kind");if(kind.equals("dataset")){JSONObject o=r.getJSONObject("original");datasetIds.add(id);names.add(o.getString("datasetId")+" / "+o.getString("asOf"));}Button b=button(history,kind+" / "+r.optString("status")+" / "+id.substring(0,Math.min(16,id.length())),()->showRecord(id));b.setTag("quantRecord_"+id);}adapter(datasetPicker,names);int index=datasetIds.indexOf(previous);if(index>=0)datasetPicker.setSelection(index);show(1);}
 private void showRecord(String id)throws Exception{JSONObject r=store.get(id);selectedId=id;summary.removeAllViews();label(summary,"完整身份: "+id);label(summary,"类型 / 状态: "+r.getString("kind")+" / "+r.optString("status"));if(r.getString("kind").equals("run")){label(summary,"冻结数据摘要: "+r.getString("datasetId"));label(summary,"材料版本数: "+r.getJSONArray("materials").length());JSONObject result=r.optJSONObject("result");if(result!=null){JSONArray ps=result.getJSONArray("parameters");for(int i=0;i<ps.length();i++){JSONObject p=ps.getJSONObject(i),m=p.getJSONObject("metrics");label(summary,String.format(Locale.ROOT,"%s · %s · OOS均值%.3f%% · 中位%.3f%% · 最差%.3f%% · 完成成交%d",p.getString("parameterId"),p.getString("admission"),m.getDouble("meanOosReturn")*100,m.getDouble("medianOosReturn")*100,m.getDouble("worstOosReturn")*100,m.getInt("tradeCount")));}}if(!r.optString("error").isEmpty())label(summary,r.getString("error"));label(summary,"探索性统计；完整记录含窗口、选参、成交、权益和未平仓证据");}else{JSONObject o=r.getJSONObject("original");label(summary,"来源: "+o.opt("source"));label(summary,"实际文件SHA256: "+r.getString("id"));label(summary,"核验状态: "+r.getString("verification"));if(r.getString("kind").equals("archive"))label(summary,"旧模型: "+o.optString("modelId")+"；未重跑，附件未独立核验");}show(1);paint(summary);}
 private void start()throws Exception{QuantResearchModel.need(pending.length()==0,"先确认或取消导入预览");QuantResearchModel.need(cancellation==null,"本页已有任务运行");JSONObject c=config();String id=datasetId();QuantResearchModel.need(!id.isEmpty(),"先导入并选择数据包");JSONObject data=store.get(id);QuantResearchModel.need(data.getString("kind").equals("dataset"),"选择的不是数据包");persist();JSONObject queued=QuantResearchModel.object("kind","run","id",UUID.randomUUID().toString(),"status","queued","datasetId",id,"config",c,"materials",new JSONArray(materials.toString()),"createdAt",Instant.now().toString());store.put(queued,new JSONObject());AtomicBoolean cancel=new AtomicBoolean(false);cancellation=cancel;status.setText("任务输入已冻结；本机模拟运行中");new Thread(()->{JSONObject job=queued;try{JSONObject next=new JSONObject(job.toString()).put("status","running");job=store.put(next,job);JSONObject result=QuantResearchModel.run(data,c,job.getJSONArray("materials"),cancel::get,(n,t)->post(()->status.setText("已计算参数 "+n+" / "+t)));synchronized(cancel){QuantResearchModel.need(!cancel.get(),"cancelled");next=new JSONObject(job.toString()).put("status","completed").put("result",result).put("finishedAt",Instant.now().toString());store.put(next,job);}post(()->status.setText("本机研究完成，结果为探索性"));}catch(Exception e){try{JSONObject next=new JSONObject(job.toString()).put("status",cancel.get()?"cancelled":"failed").put("error",e.getMessage()==null?e.toString():e.getMessage()).put("finishedAt",Instant.now().toString());store.put(next,job);post(()->status.setText(cancel.get()?"任务已取消，冻结输入保留":"任务失败："+e.getMessage()));}catch(Exception saveError){post(()->status.setText("任务状态写入失败："+saveError.getMessage()+"；原研究库未重建"));}}post(()->{cancellation=null;guard(()->{refresh();showRecord(queued.getString("id"));});});},"QuantResearch-local").start();}
 private void cancelRun(){AtomicBoolean cancel=cancellation;if(cancel!=null)synchronized(cancel){cancel.set(true);}}
 private void showText(String t){selectedModelId="";readerText=t;readerOffset=0;renderReader();show(2);}
 private void renderReader(){int total=readerText.codePointCount(0,readerText.length()),start=readerText.offsetByCodePoints(0,Math.min(readerOffset,total)),end=readerText.offsetByCodePoints(0,Math.min(readerOffset+24000,total));reader.setText(readerText.substring(start,end));status.setText("完整记录分段读取 "+readerOffset+"–"+Math.min(readerOffset+24000,total)+" / "+total+" 字符；导出保留全量");}
 void openModelResult(String id)throws Exception{showText(QuantModelResult.summary(QuantModelResult.verify(modelArchive.read(id))).toString(2));selectedModelId=id;}
 public void previewImport(String raw)throws Exception{QuantResearchModel.need(cancellation==null,"本页运行结束后再导入");if(QuantResearchJson.parse(raw).optString("schema").equals("webstock.quant.native-result.v1")){QuantResearchModel.need(pending.length()==0,"先确认或取消现有预览");JSONObject result=QuantModelResult.verify(raw);modelPending=raw;showText(QuantModelResult.summary(result).toString(2));status.setText("仅当页预览，附件摘要已核对；确认后独立归档。此设备未执行训练。");return;}modelPending="";pending=QuantResearchModel.importText(raw);pendingBaseline=store.read();showText(pending.getJSONObject("original").toString(2));status.setText("仅预览，未写入；检查来源/日期/模型后确认。旧结果附件仍未核验。");persist();}
 public void confirmImport()throws Exception{if(!modelPending.isEmpty()){modelArchive.save(modelPending);selectedModelId=QuantModelResult.verify(modelPending).getString("id");modelPending="";status.setText("完整结果独立归档；再次读取会重新核对附件；手机未执行训练");return;}QuantResearchModel.need(pending.length()>0,"没有待确认预览");store.merge(pending,pendingBaseline);pending=new JSONObject();pendingBaseline=new JSONObject();refresh();persist();status.setText("导入完成，原始文件完整保留");}
 public void cancelImport(){if(!modelPending.isEmpty()){readerText="";readerOffset=0;}modelPending="";pending=new JSONObject();pendingBaseline=new JSONObject();show(0);status.setText("预览已取消");guard(this::persist);}
 public boolean back(){if(cancellation!=null)cancelRun();if(mode==2){if(pending.length()>0||!modelPending.isEmpty())cancelImport();else show(1);return true;}if(mode==1){show(0);return true;}guard(this::persist);return false;}
 private JSONObject state()throws Exception{JSONObject texts=new JSONObject();for(String k:KEYS)texts.put(k,fields.get(k).getText().toString());return QuantResearchModel.object("schema","quant-native-view/v1","familyIndex",familyPicker.getSelectedItemPosition(),"fields",texts,"parametersText",parameters.getText().toString(),"datasetId",datasetId(),"materials",materials,"selectedId",selectedId,"pending",pending,"pendingBaseline",pendingBaseline,"readerText",modelPending.isEmpty()?readerText:"","readerOffset",modelPending.isEmpty()?readerOffset:0,"selectedModelId",selectedModelId,"mode",modelPending.isEmpty()?mode:0);}
 public Bundle saveState(){Bundle b=new Bundle();guard(()->{persist();b.putString("quantResearchViewFile",store.filePath().getAbsolutePath());b.putString("quantResearchViewFingerprint",PersonMethodModel.hash(viewBaseline));});return b;}
 public void restoreState(Bundle b){if(b==null)return;String marker=b.getString("quantResearchViewFile");if(marker!=null)guard(()->{QuantResearchModel.need(marker.equals(store.filePath().getAbsolutePath()),"状态标记不属于本研究库");JSONObject saved=store.loadView();QuantResearchModel.need(saved.length()>0,"侧文件状态缺失，未重建");QuantResearchModel.need(PersonMethodModel.hash(saved).equals(b.getString("quantResearchViewFingerprint")),"侧文件已变更，请显式重读草稿");viewBaseline=new JSONObject(saved.toString());applyState(saved);viewWritable=true;});}
 private void applyState(JSONObject o)throws Exception{QuantResearchModel.need(o.getString("schema").equals("quant-native-view/v1"),"草稿格式无效");int f=o.getInt("familyIndex");QuantResearchModel.need(f>=0&&f<QuantResearchModel.FAMILIES.length,"草稿策略无效");JSONObject texts=o.getJSONObject("fields");filling=true;familyPicker.setSelection(f);for(String k:KEYS)fields.get(k).setText(texts.getString(k));parameters.setText(o.getString("parametersText"));materials=o.getJSONArray("materials");selectedId=o.optString("selectedId");int i=datasetIds.indexOf(o.getString("datasetId"));if(i>=0)datasetPicker.setSelection(i);pending=o.optJSONObject("pending")==null?new JSONObject():o.getJSONObject("pending");pendingBaseline=o.optJSONObject("pendingBaseline")==null?new JSONObject():o.getJSONObject("pendingBaseline");if(pending.length()>0)QuantResearchModel.need(QuantResearchStore.equal(pending,QuantResearchModel.importText(pending.getString("rawUtf8"))),"预览原文不一致");readerText=o.optString("readerText");readerOffset=o.optInt("readerOffset");QuantResearchModel.need(readerOffset>=0&&readerOffset<=readerText.codePointCount(0,readerText.length()),"正文位置无效");int savedMode=o.optInt("mode");QuantResearchModel.need(savedMode>=0&&savedMode<=2,"页面模式无效");if(savedMode==2&&!o.optString("selectedModelId").isEmpty())openModelResult(o.getString("selectedModelId"));else{if(savedMode==1&&!selectedId.isEmpty())showRecord(selectedId);else show(savedMode);if(savedMode==2)renderReader();}filling=false;}
